async function readResult(response) {
  if (!response.ok) throw new Error('request failed');
  if (response.status === 204) return null;
  return response.json();
}
(async () => {
  const result = await readResult({ok: true, status: 204, json() {throw new Error('no body');}});
  console.log(result === null ? 'deleted' : 'unexpected');
})();

const pending = {};
let latest = 0;
let shown = [];
function request(query) {
  return new Promise(resolve => { pending[query] = resolve; });
}
async function search(query) {
  const requestId = ++latest;
  const items = await request(query);
  if (requestId !== latest) return;
  shown = items;
}
(async () => {
  const oldRequest = search('ق');
  const currentRequest = search('قلم');
  pending['قلم']([{name: 'قلم'}]);
  await currentRequest;
  pending['ق']([{name: 'قائمة قديمة'}]);
  await oldRequest;
  console.log(shown[0].name);
})();
